/**
 * RÉVÉLER OU MASQUER UNE PAGE TERMINAL
 *
 * PAGE_UUID doit désigner une page Terminal importée dans le monde.
 * MODE accepte trois valeurs :
 *   "show"   : rendre la page visible;
 *   "hide"   : masquer la page;
 *   "toggle" : inverser son état actuel.
 *
 * Une page masquée disparaît des menus automatiques des joueurs. Son contenu
 * n’est pas supprimé et peut être révélé de nouveau avec la même macro.
 */

// ── CONFIGURATION À MODIFIER ──────────────────────────────────
const PAGE_UUID = "JournalEntry.REMPLACEZ_MOI.JournalEntryPage.REMPLACEZ_MOI";
const MODE = "toggle"; // "show", "hide" ou "toggle"
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("Cette macro est réservée au MJ.");
if (!game.modules.get("retro-crt-terminal")?.active) {
  return ui.notifications.error("Retro CRT Terminal n’est pas actif.");
}
if (!PAGE_UUID || PAGE_UUID.includes("REMPLACEZ_MOI")) {
  return ui.notifications.warn("Modifiez PAGE_UUID dans la configuration de la macro.");
}
if (!["show", "hide", "toggle"].includes(MODE)) {
  return ui.notifications.error("MODE doit être show, hide ou toggle.");
}

const page = await foundry.utils.fromUuid(PAGE_UUID);
if (page?.documentName !== "JournalEntryPage" || page.type !== "retro-crt-terminal.terminal") {
  return ui.notifications.error("PAGE_UUID ne désigne pas une page Retro CRT Terminal.");
}

const current = page.system.release.visibility;
const visibility = MODE === "show" ? "visible" : MODE === "hide" ? "hidden" : current === "hidden" ? "visible" : "hidden";
await page.update({ "system.release.visibility": visibility });
ui.notifications.info(`${page.name} est maintenant ${visibility === "visible" ? "visible" : "masquée"}.`);
